package com.jagan.healthcare.controller;
import com.jagan.healthcare.model.UserAccount; import com.jagan.healthcare.repository.UserAccountRepository; import jakarta.servlet.http.HttpSession; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/profile") @CrossOrigin(origins="*") public class ProfileController { private final UserAccountRepository repo; public ProfileController(UserAccountRepository repo){this.repo=repo;}
 @GetMapping public ResponseEntity<?> get(HttpSession s){String email=(String)s.getAttribute("userEmail");if(email==null)return ResponseEntity.status(401).body(Map.of("message","Please login first."));UserAccount u=repo.findByEmailIgnoreCase(email).orElseThrow();return ResponseEntity.ok(Map.of("name",u.getName(),"email",u.getEmail(),"phone",u.getPhone()==null?"":u.getPhone(),"role",u.getRole()));}
 @PutMapping public ResponseEntity<?> update(@RequestBody Map<String,String> body,HttpSession s){String email=(String)s.getAttribute("userEmail");if(email==null)return ResponseEntity.status(401).body(Map.of("message","Please login first."));UserAccount u=repo.findByEmailIgnoreCase(email).orElseThrow();String name=body.get("name"),phone=body.get("phone");if(name!=null&&!name.isBlank())u.setName(name.trim());u.setPhone(phone);repo.save(u);return ResponseEntity.ok(Map.of("message","Profile updated successfully."));}
}
